// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 amount, uint256 topUp) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        topUp = bound(topUp, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        bool firstSuccess;
        try c.go{value: amount}() { firstSuccess = true; } catch { firstSuccess = false; }
        bool topUpSuccess;
        try c.go{value: topUp}() { topUpSuccess = true; } catch { topUpSuccess = false; }
        bool secondSuccess;
        try c.go() { secondSuccess = true; } catch { secondSuccess = false; }
        assertTrue(!(firstSuccess && topUpSuccess && secondSuccess) || address(c).balance == 0);
    }

    function testFuzz_run(uint256 amount, uint256 topUp) public {
        _run(amount, topUp);
    }

    receive() external payable {}
}
